using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and analysis." },
        new() { Code = "ENG", Name = "English", Description = "Literature, writing, and linguistic studies." },
        new() { Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Code = "HIST", Name = "History", Description = "Exploration of past events, civilizations, and cultural developments." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming and has authored two textbooks on Python.", DepartmentCode = "CS", IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and holds a Ph.D. from MIT in theoretical computer science.", DepartmentCode = "CS", IsFeatured = true },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect at Oracle for 10 years before joining academia.", DepartmentCode = "CS", IsFeatured = false },
        new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a renowned mathematician with publications in differential equations and mathematical modeling.", DepartmentCode = "MATH", IsFeatured = true },
        new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to computer graphics and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Park", InstructorBio = "Dr. Park's research focuses on computational linear algebra and its applications in data science.", DepartmentCode = "MATH", IsFeatured = false },
        new() { Id = 6, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a statistician who has consulted for major healthcare organizations on clinical trial design.", DepartmentCode = "MATH", IsFeatured = false },
        new() { Id = 7, Code = "ENG 101", Title = "English Composition", Description = "Develop skills in academic writing, argumentation, research methods, and critical reading.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Diana Wells", InstructorBio = "Prof. Wells is a published author and writing coach with expertise in rhetoric and composition pedagogy.", DepartmentCode = "ENG", IsFeatured = false },
        new() { Id = 8, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and society.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson specializes in 20th-century American fiction and has published extensively on Toni Morrison and James Baldwin.", DepartmentCode = "ENG", IsFeatured = true },
        new() { Id = 9, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM, Lab: Thu 2:00–4:00 PM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura is an experimental physicist whose research focuses on condensed matter physics.", DepartmentCode = "PHYS", IsFeatured = false },
        new() { Id = 10, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Victor Petrov", InstructorBio = "Dr. Petrov has 20 years of experience in electromagnetic theory and holds multiple patents in antenna design.", DepartmentCode = "PHYS", IsFeatured = false },
        new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the medieval period.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Catherine Okafor", InstructorBio = "Dr. Okafor is a historian specializing in ancient Mediterranean and West African civilizations.", DepartmentCode = "HIST", IsFeatured = false },
        new() { Id = 12, Code = "HIST 250", Title = "Modern European History", Description = "Europe from the Enlightenment through the 21st century, covering revolutions, world wars, and European integration.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Franz Weber", InstructorBio = "Dr. Weber is a specialist in 20th-century European political history and has authored three books on post-war reconstruction.", DepartmentCode = "HIST", IsFeatured = true },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? departmentCode)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

